"""Flatten arbitrarily nested dictionaries into dot-notation keys."""

from collections.abc import Mapping


def parse_expression(data: dict, parent_key: str = "", sep: str = ".") -> dict:
    """Flatten a nested dictionary into dot-notation keys.

    Args:
        data: The nested dictionary to flatten.
        parent_key: Prefix for keys (used internally for recursion).
        sep: Separator between key segments.

    Returns:
        A flat dictionary with dot-joined keys.
    """
    items: list[tuple[str, object]] = []
    for key, value in data.items():
        new_key = f"{parent_key}{sep}{key}" if parent_key else key
        if isinstance(value, Mapping):
            items.extend(parse_expression(value, new_key, sep=sep).items())
        else:
            items.append((new_key, value))
    return dict(items)


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_flat_dict():
    assert parse_expression({"a": 1, "b": 2}) == {"a": 1, "b": 2}


def test_one_level_nesting():
    data = {"a": {"b": 1}}
    assert parse_expression(data) == {"a.b": 1}


def test_deep_nesting():
    data = {"a": {"b": {"c": {"d": 42}}}}
    assert parse_expression(data) == {"a.b.c.d": 42}


def test_mixed_types():
    data = {"name": "alice", "scores": [1, 2], "active": True}
    assert parse_expression(data) == {"name": "alice", "scores": [1, 2], "active": True}


def test_nested_with_list_values():
    data = {"a": {"b": [10, 20]}}
    assert parse_expression(data) == {"a.b": [10, 20]}


def test_multiple_nested_branches():
    data = {
        "server": {"host": "localhost", "port": 8080},
        "db": {"creds": {"user": "admin", "pass": "s3cret"}},
    }
    expected = {
        "server.host": "localhost",
        "server.port": 8080,
        "db.creds.user": "admin",
        "db.creds.pass": "s3cret",
    }
    assert parse_expression(data) == expected


def test_empty_dict():
    assert parse_expression({}) == {}


def test_none_values():
    data = {"a": None, "b": {"c": None}}
    assert parse_expression(data) == {"a": None, "b.c": None}


def test_numeric_keys():
    data = {0: {"1": "val"}}
    assert parse_expression(data) == {"0.1": "val"}


def test_custom_separator():
    data = {"a": {"b": 1}}
    assert parse_expression(data, sep="/") == {"a/b": 1}


def test_nested_empty_dict():
    data = {"a": {"b": {}}}
    assert parse_expression(data) == {}


def test_overlapping_keys_last_wins():
    data = {"a": {"b": 1}, "a.b": 2}
    result = parse_expression(data)
    assert result["a.b"] == 2


def test_single_key_no_nesting():
    assert parse_expression({"key": "value"}) == {"key": "value"}


def test_deeply_nested_mixed():
    data = {
        "level1": {
            "level2": {
                "level3": {
                    "leaf": "deep",
                    "sibling": "also_deep",
                },
                "mid_leaf": 99,
            }
        },
        "top_leaf": "shallow",
    }
    expected = {
        "level1.level2.level3.leaf": "deep",
        "level1.level2.level3.sibling": "also_deep",
        "level1.level2.mid_leaf": 99,
        "top_leaf": "shallow",
    }
    assert parse_expression(data) == expected


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])

